func check_uncache(ctx Context, _k any, c0 string, c *valcache, r []*valcache) {
	k := unloc(_k.(Value))
	if a, ok := k.(*argumented); ok { k = a.Value }

	t := typeof(k)
	ks := sf("%v %s", c0, k)
	vs := sf("%v", r)

	if c0 == "{}" && (vs == "[]" || vs == "[{}]") { return }

	rs, y := checkpoints_uncache[ks]
	if !y {
		if p := _project(ctx); p != nil { switch {
		case strings.HasSuffix(p.spec, ".smart/modules/app/.base"): return
		case strings.HasSuffix(p.spec, ".smart/modules/lib/unwind"): return
		case strings.HasSuffix(p.spec, ".smart/modules/lib/c++abi"): return
		case strings.HasSuffix(p.spec, ".smart/modules/lib/c++inc"): return
		case strings.HasSuffix(p.spec, ".smart/modules/lib/c++"): return
		case p.spec == "testdata/configuration": return
		}}
		
		if false { prompt(ctx, `	"%s":"%s", //uncache`+"\n", ks, vs); flush(ctx) } else
		if false { prompt(ctx, "	`%s`:`%s`, //uncache\n", ks, vs); flush(ctx) } else
		{ debug(pc(ctx,_k),
			_f("%s: `%s`:`%s`,", t, ks, vs),
			_f("%s", _project(ctx).spec),
			callstack{num:32,/* stop:"smart.hit" */}, trace{}) }
	} else if vs != rs && !(vs == "[]" && rs == "[{}]") && !(vs == "[{}]" && rs == "[]") {
		if false { prompt(ctx, `	"%s":"%s", //uncache: != %s`+"\n", ks, vs, rs); flush(ctx) } else
		if false { prompt(ctx, "	`%s`:`%s`, //uncache: != %s\n", ks, vs, rs); flush(ctx) } else
		{ debug(pc(ctx,_k),
			_f("%s: %v", t, ks),
			_f("got: %v", vs),
			_f("!= : %v", rs),
			callstack{num:32,/* stop:"smart.hit" */}, trace{}) }
	}
}

